/*
 * A074883  Triangle generated by Pascal's rule, except begin and end the n-th
 *          row with sigma(n).
 * https://oeis.org/A074883
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 40, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   alloc_seq_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A074883: Triangular array whose first and last element of the n-th row
   is sigma(n) (sum of divisors of n); interior elements are the sum of
   the two elements above them (Pascal’s rule).  The flattened array
   is returned by a(n).  The implementation uses a sieve for sigma
   values and O(r²) triangle construction, where r ≈ √(2n).  It
   performs well for n up to about 10 000. */
#include <stdlib.h>
#include "../utils/alloc_seq_array.h"

seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;

    /* Find row r such that T(r‑1) < n ≤ T(r),  T(k)=k(k+1)/2 */
    idx_t r = 1;
    while ((unsigned __int128)r * (r + 1) / 2 < n)
        ++r;

    /* Column within the row */
    idx_t prev_tri = (unsigned __int128)(r - 1) * r / 2;
    idx_t c = n - prev_tri;           /* 1‑based column */

    /* Allocate arrays for sigma, previous row and current row */
    seq_t *sigma = alloc_seq_array(r + 1);
    seq_t *prev  = alloc_seq_array(r + 1);
    seq_t *cur   = alloc_seq_array(r + 1);

    /* Initialise sigma to zero */
    for (idx_t i = 0; i <= r; ++i)
        sigma[i] = (seq_t)0;

    /* Compute sigma values for 1..r (simple divisor sieve) */
    for (idx_t d = 1; d <= r; ++d) {
        for (idx_t j = d; j <= r; j += d)
            sigma[j] += (seq_t)d;
    }

    /* Build the triangle row by row */
    prev[1] = sigma[1];
    seq_t result;
    if (r == 1) {                 /* first row is a single element */
        result = prev[1];
    } else {
        for (idx_t row = 2; row <= r; ++row) {
            cur[1] = sigma[row];
            for (idx_t col = 2; col < row; ++col)
                cur[col] = prev[col - 1] + prev[col];
            cur[row] = sigma[row];

            if (row == r)
                result = cur[c];

            /* swap row pointers for next iteration */
            seq_t *tmp = prev;
            prev = cur;
            cur = tmp;
        }
    }

    free(prev);
    free(cur);
    free(sigma);
    return result;
}
